//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gDepCd = js_dep_cd;
scwin.gLdMktTp = js_market;
scwin.vScrenID = 'ULDSTF30004.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_resizeToWin = function() {
    frame.Width = 610;
    frame.Height = 580;
};
scwin.fn_Init = function() {
    //if(gLdMktTp == '1' || gDepCd == 'ZSYS' || js_dep_cd == '1M30')	panel_reg.style.visibility = "";
    panel_reg.style.visibility = "";
};
scwin.fn_setHeader = function() {
    dts_STAT_CD.DataID = "/CodeAction.do?method=listStatCd&For=C";
    dts_STAT_CD.Reset();
    var url = "/DisclosureSchedule.do?method=listEmptyAdm";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Grid.DataID = url;
    dts_Grid.Reset();
    dts_Master.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SCHEDULE_INSERT_IN";
    dts_Master.Reset();
    dts_Master.insertRow();
};
scwin.fn_HideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    $c.stf.showObj(txb_ACPT_NO, false);
};
scwin.fn_CheckPeriod = function() {
    if ($c.stf.getObjectValue(edt_SDate) == "") {
        $c.win.alert("[관리기간]을 입력하세요.");
        edt_SDate.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_EDate) == "") {
        $c.win.alert("[관리기간]을 입력하세요.");
        edt_EDate.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_std) == "") {
        $c.win.alert("[관리기준]을 선택하세요.");
        cmb_std.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_prd) == "") {
        $c.win.alert("[관리주기]를 선택하세요.");
        cmb_prd.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_ord) == "") {
        $c.win.alert("[정/역순]을 선택하세요.");
        cmb_ord.focus();
        return false;
    }
    return true;
};
scwin.fn_SetPeriod = function() {
    dts_Grid.removeAll();
    var sdate = $c.stf.getObjectValue(edt_SDate);
    var edate = $c.stf.getObjectValue(edt_EDate);
    var std = $c.stf.getObjectValue(cmb_std);
    var prd = $c.stf.getObjectValue(cmb_prd);
    var ord = $c.stf.getObjectValue(cmb_ord);

    //alert(sdate + "\n" + edate + "\n" + std + "\n" + prd + "\n" + ord);
    if (ord == '1') //정순

    {
        var begday = sdate.substr(6, 2); //입력받은 시작일
        if (std == '1') //일자기준

        {
            for (var i = 1; sdate < edate; i++) {
                sdate = scwin.fn_GetPlusMonth(sdate.substr(0, 4), sdate.substr(4, 2), begday, i == 1 ? 0 : prd);
                var maxday = $c.ut.cGetMaxDay(sdate.substr(0, 4), sdate.substr(4, 2)); //해당월의 막날
                if (maxday < begday) sdate = $c.ut.cGetMinusMonth(sdate.substr(0, 4), sdate.substr(4, 2), maxday, 0);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", sdate);
                }
            }
        } else if (std == '2') //말일기준

        {
            for (var i = 1; sdate < edate; i++) {
                sdate = scwin.fn_GetPlusMonth(sdate.substr(0, 4), sdate.substr(4, 2), edate.substr(6, 2), i == 1 ? 0 : prd);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", scwin.fn_GetPlusMonth(sdate.substr(0, 4), sdate.substr(4, 2), $c.ut.cGetMaxDay(sdate.substr(0, 4), sdate.substr(4, 2)), 0));
                }
            }
        }
    } else if (ord == '2') //역순

    {
        var endday = edate.substr(6, 2); //입력받은 종료일
        if (std == '1') //일자기준

        {
            for (var i = 1; sdate < edate; i++) {
                edate = $c.ut.cGetMinusMonth(edate.substr(0, 4), edate.substr(4, 2), endday, i == 1 ? 0 : prd);
                var maxday = $c.ut.cGetMaxDay(edate.substr(0, 4), edate.substr(4, 2)); //해당월의 막날
                if (maxday < endday) edate = $c.ut.cGetMinusMonth(edate.substr(0, 4), edate.substr(4, 2), maxday, 0);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", edate);
                }
            }
        } else if (std == '2') //말일기준

        {
            var yyyy = edate.substr(0, 4);
            var mm = edate.substr(4, 2);
            var maxday = $c.ut.cGetMaxDay(yyyy, mm); //해당월의 막날

            if (maxday != endday) //말일아니면

            {
                edate = scwin.fn_GetPlusMonth(yyyy, mm, '01', 0); //이번달 1일 기준

            } else {
                edate = scwin.fn_GetPlusMonth(yyyy, mm, '01', 1); //다음달 1일 기준

            }
            for (var i = 1; sdate < edate; i++) {
                edate = $c.ut.cGetMinusMonth(edate.substr(0, 4), edate.substr(4, 2), '01', i == 1 ? 0 : prd);
                if (sdate < edate) {
                    dts_Grid.insertRow();
                    dts_Grid.setCellData(i, "ADM_DEADLINE_DD", $c.ut.cGetMinusDate2(edate, 1));
                }
            }
        }
    }

    //휴일체크
    trs_Read.Action = "/DisclosureSchedule.do?method=readHolidayCheck&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(I:pInput1=dts_Grid,O:pOutput1=dts_Obj)";
    trs_Read.Post();
};
scwin.fn_GetPlusMonth = function(yyyy, mm, dd, val) {
    var iYear = new Number(yyyy);
    var iMonth = new Number(mm);
    var iDay = new Number(dd);
    var ival = new Number(val);
    var iAddYear = 0;
    if (ival >= 12) {
        iAddYear = new Number(ival / 12);
        iYear = iYear + iAddYear;
        iMonth = iMonth + (ival % 12);
    } else {
        ival += iMonth;
        if (ival > 12) {
            iYear = iYear + 1;
            iMonth = ival - 12;
        } else {
            iMonth = ival;
        }
    }
    iMaxDay = $c.ut.cGetMaxDay(iYear, iMonth);
    if (iDay > iMaxDay) {
        iDay = iMaxDay;
    }
    return "" + iYear.toString() + $c.ut.cGetZero(iMonth.toString(), 2) + $c.ut.cGetZero(iDay.toString(), 2);
};
scwin.fn_Save = function() {
    if (scwin.fn_CheckForm()) {
        var res = window.confirm("[저장]하시겠습니까?");
        if (res) {
            dts_Master.setCellData(1, "EMP_NO", js_emp_no);
            trs_Save.Action = "/DisclosureSchedule.do?method=registerMultipleSchedule&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInputMaster=dts_Master,I:pInputDetail=dts_Grid)";
            trs_Save.Post();
        }
    }
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    /*
    if (getObjectValue(txb_COM_NM) == "")
    {
    	alert("[회사]를 선택하세요.");txb_COM_NM.focus();return false;
    }	

    if (getObjectValue(txb_ACPT_NO) == "")
    {
    	alert("[공시]를 선택하세요.");txb_ACPT_NO.focus();return false;
    }	
    */
    if ($c.stf.getObjectValue(txb_RptNm) == "") {
        $c.win.alert("[공시]를 선택하세요.");
        txb_RptNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_DISCLS_PUBL_DDTM) == "") {
        $c.win.alert("[공시일]를 입력하세요.");
        edt_DISCLS_PUBL_DDTM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_DISCLS_SCHDL_ACT_STAT_CD) == "") {
        $c.win.alert("[일정상태]를 선택하세요.");
        cmb_DISCLS_SCHDL_ACT_STAT_CD.focus();
        return false;
    }
    // detail 검사
    var total = dts_Grid.getTotalRow();
    for (var i = 0; i < total; i++) {
        var vADM_DEADLINE_DD = dts_Grid.getCellData(i, "ADM_DEADLINE_DD");
        var vSCHDL_ADM_ITM_TP_NM = dts_Grid.getCellData(i, "SCHDL_ADM_ITM_TP_CD");
        if (vADM_DEADLINE_DD == "" && vSCHDL_ADM_ITM_TP_NM != "") {
            $c.win.alert(" 관리기한을 입력하지 않았습니다.");
            return false;
        }
        if (vSCHDL_ADM_ITM_TP_NM == "" && vADM_DEADLINE_DD != "") {
            $c.win.alert(" 관리항목을 입력하지 않았습니다.");
            return false;
        }
    }
    /*if (total != dTotal)
		{
			alert("저장할 일정이 없거나 관리기한을 입력하지 않았습니다.");return false;
		} */
    // 관리일자가 하나라도 들어왔으면.
    return true;
};
scwin.fn_openDiscls = async function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요");
        txb_ISUR_CD.focus();
        return;
    }
    var vISUR_CD = $c.stf.getObjectValue(txb_ISUR_CD);
    await $c.frame.CreateDialogFrame("wndDiscls|ISUR_CD=" + vISUR_CD, "/dsclmgt/ULDSTF30005.gfm", "공시선택", 10, 10, 10, 20, "window");
};
scwin.btn_AddRow_onclick = function() {
    dts_Grid.insertRow();
};
scwin.btn_DelRow_onclick = function() {
    $c.cp.removeRow(dts_Grid, dts_Grid.getRowPosition());
};
scwin.grd_Grid_OnPopup = async function(row, colid, data) {
    if (colid == "ADM_DEADLINE_DD") {
        // 관리기한 ADM_DEADLINE_DD => 달력 띄워야함.
        dts_Grid.setCellData(dts_Grid.getRowPosition(), "ADM_DEADLINE_DD", vResVal);
    } else {
        // 관리항목 SCHDL_ADM_ITM_TP_CD => 관리항목선택창(30002) 띄워야함.
        await $c.frame.CreateDialogFrame("ONLYFORGRID", "/dsclmgt/ULDSTF30002.gfm", "관리항목유형", 10, 10, 10, 20, "window");
    }
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    //alert_parse(dts_Grid.Text, ",");

};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
};
scwin.trs_Read_OnSuccess = function() {
    dts_Grid.removeAll();
    $c.stf.CopyDataSet(dts_Obj, dts_Grid, "");
};
scwin.dts_Master_OnLoadCompleted = function(rowcount) {
    //alert_parse(dts_Master.Text, ",");

};
scwin.btn_Search_Rpt_Nm_onclick = function() {
    scwin.fn_openDiscls();
};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    if (colid == "ADM_DEADLINE_DD") {
        // true => 빠져나옴. false => 갇힘.
        var sDate = dts_Grid.getCellData(row, "ADM_DEADLINE_DD");
        var res = $c.ut.isDate(sDate);
        if (res) {
            return true;
        } else {
            $c.win.alert("[관리기한]의 날짜형식이 정확하지 않습니다.");
            return false;
        }
    }
    return true;
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.btn_Search_Isur_Cd_onclick = function() {
    $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_reg_onclick = function() {
    if (scwin.fn_CheckPeriod()) {
        if ($c.stf.compareFromToDate(edt_SDate, edt_EDate, "시작일", "종료일")) {
            scwin.fn_SetPeriod();
        }
    }
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_resizeToWin();
    scwin.fn_setHeader();
    scwin.fn_Init();
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};
